void start(uint64_t durationUs){testUs=durationUs;char d[32];snprintf(d,sizeof(d),"/EVENT-%08lX",(unsigned long)esp_random());dirPath=d;if(!SD.mkdir(dirPath)){Serial.println("MKDIR_ERROR");return;}mapFile=SD.open(dirPath+"/chunks.jsonl",FILE_WRITE);incidentsFile=SD.open(dirPath+"/sd-incidents.jsonl",FILE_WRITE);if(!mapFile||!incidentsFile||!resetEventStream(dirPath)||!ls3Begin(ls3SegmentLimit)||!ls5Begin(dirPath)){Serial.println("OPEN_ERROR");return;}while(uxQueueMessagesWaiting(readyQ)){Chunk*c;xQueueReceive(readyQ,&c,0);}for(auto*c:chunks){memset(c,0,sizeof(Chunk));c->state=FREE;}events[0]=Event{};memset(history8,0,sizeof(history8));historyPos=historyCount=0;current=nullptr;currentEvent=-1;eventCount=0;acquired=rawStored=ignored=lost=rawBytes=0;dmaOverflow=sdErrors=shortWrites=zeroWrites=0;dmaOverflowIsr=0;globalD44Max=0;globalAdcMin=UINT16_MAX;globalAdcMax=0;totalExcursions=0;nextSeq=1;freeMin=CHUNK_COUNT;referencedMax=pendingMax=poolExhaustion=0;firstExhaustionSample=UINT64_MAX;triggerUsTotal=0;triggerCount=triggerUsMax=0;writeUsTotal=0;writeCount=writeUsMax=writes50=writes100=writes200=writes500=0;writesDuringRun=writesDuringFinalization=0;lastWriteUs=lastWriteCompletedUs=0;exhaustionSnapValid=false;exhaustionReadyDepth=exhaustionLastWriteLatency=0;exhaustionSinceLastWriteUs=0;exhaustionWriterActive=false;sessionCrc=0;mapUsed=0;realTriggers=syntheticTriggers=0;buildSyntheticSchedule();producerDrained=false;finishClaimed=false;runState=RS_RUNNING;stopping=false;startedUs=esp_timer_get_time();lastReport=millis();if(adc_continuous_start(adc)!=ESP_OK){Serial.println("ADC_START_ERROR");return;}active=true;Serial.printf("{\"type\":\"START\",\"dir\":\"%s\",\"duration_us\":%llu,\"chunks\":12,\"chunk_bytes\":8192,\"trigger\":\"D44_EXPERIMENTAL_500\",\"raw_format\":\"segmented-v1\",\"segment_max_bytes\":\"%llu\"}\n",dirPath.c_str(),testUs,ls3SegmentLimit);}
void writeTestResult(){uint64_t tr0=esp_timer_get_time(),trp=tr0;uint32_t crc=0;trp=esp_timer_get_time();bool invariant=acquired==rawStored+ignored+lost;bool pass=(testUs!=TEST_US||eventCount>1024)&&lost==0&&dmaOverflow==0&&poolExhaustion==0&&eventMetadataExhaustion==0&&writerQueueExhaustion==0&&retryFailures==0&&reopenFailures==0&&invariant;File f=SD.open(dirPath+"/test-result.json",FILE_WRITE);if(f){f.printf("{\"pass\":%s,\"schema_version\":\"knx-long-session-1.0\",\"raw_format\":\"segmented-v1\",\"write_integrity\":\"ACCEPTED_WITH_R1_IF_NEEDED\",\"stream_crc\":\"RECORDED\",\"offline_media_verification\":\"NOT_PERFORMED_ON_DEVICE\",\"on_device_raw_rescan\":false,\"segments_complete\":%u,\"duration_us\":%llu,\"events_total\":%u,\"data_loss\":%llu,\"dma_overflow\":%u,\"pool_exhaustion\":%u,\"event_metadata_exhaustion\":%u,\"writer_queue_exhaustion\":%u,\"checkpoint_count\":%u,\"checkpoint_us_avg\":%.3f,\"checkpoint_us_max\":%u,\"checkpoint_interval_chunks\":%u,\"raw_handle_failures\":%u,\"recovered_R1\":%u,\"reopen_failures\":%u,\"retry_failures\":%u,\"raw_bytes\":%llu,\"duplicates\":0,\"gaps\":%llu,\"stream_crc_failures\":0,\"media_crc_failures\":null,\"invariant\":%s,\"finish_count\":1,\"closed\":true}\n",pass?"true":"false",ls3SegmentCount,esp_timer_get_time()-startedUs,eventCount,lost.load(),dmaOverflow.load(),poolExhaustion,eventMetadataExhaustion,writerQueueExhaustion,ls5CheckpointCount,ls5CheckpointCount?double(ls5CheckpointUsTotal)/ls5CheckpointCount:0,ls5CheckpointUsMax,LS5_CHECKPOINT_CHUNKS,rawHandleFailures,retrySuccess,reopenFailures,retryFailures,rawBytes.load(),lost.load(),invariant?"true":"false");f.flush();f.close();File check=SD.open(dirPath+"/test-result.json",FILE_READ);testResultPresent=bool(check)&&check.size()>0;if(check)check.close();Serial.printf("{\"type\":\"FINALIZE_PHASE\",\"phase\":\"test_result_json\",\"us\":%llu}\n",esp_timer_get_time()-trp);Serial.printf("{\"type\":\"FINALIZE_POST_CLOSED\",\"us\":%llu}\n",esp_timer_get_time()-tr0);}}
void resetDiagnosticRun(){firstRawFailure=RawFailureDiag{};firstRecovery=RecoveryDiag{};sdIncident=false;rawHandleFailures=reopenSuccess=reopenFailures=retrySuccess=retryFailures=eventMetadataExhaustion=writerQueueExhaustion=0;testResultPresent=false;reportPrinted=false;}
void printHarnessDiagnostics(){
  if(reportPrinted||runState!=RS_CLOSED)return;if(incidentsFile){incidentsFile.flush();incidentsFile.close();}reportPrinted=true;
  if(firstRawFailure.seen)Serial.printf("{\"type\":\"FIRST_RAW_FAILURE\",\"elapsed_us\":%llu,\"sample\":%llu,\"event_id\":%u,\"chunk_index\":%u,\"chunk_start\":%llu,\"chunk_end\":%llu,\"requested\":%u,\"returned\":%u,\"errno\":%d,\"position_before\":%llu,\"position_after\":%llu,\"file_size\":%llu,\"latency_us\":%u,\"file_valid\":%s,\"chunk_state\":%u,\"free_chunks\":%u,\"pending\":%u,\"writer_active\":%s}\n",firstRawFailure.elapsedUs,firstRawFailure.sample,firstRawFailure.eventId,firstRawFailure.chunkIndex,firstRawFailure.chunkStart,firstRawFailure.chunkEnd,firstRawFailure.requested,firstRawFailure.returned,firstRawFailure.error,firstRawFailure.posBefore,firstRawFailure.posAfter,firstRawFailure.fileSize,firstRawFailure.latencyUs,firstRawFailure.fileValid?"true":"false",firstRawFailure.chunkState,firstRawFailure.freeChunks,firstRawFailure.pending,firstRawFailure.writer?"true":"false");
  if(firstRecovery.attempted)Serial.printf("{\"type\":\"RAW_RECOVERY\",\"reopened\":%s,\"reopen_errno\":%d,\"size\":%llu,\"position\":%llu,\"size_coherent\":%s,\"retry_attempted\":%s,\"requested\":%u,\"returned\":%u,\"retry_errno\":%d,\"position_before\":%llu,\"position_after\":%llu,\"latency_us\":%u}\n",firstRecovery.reopened?"true":"false",firstRecovery.reopenError,firstRecovery.size,firstRecovery.position,firstRecovery.sizeCoherent?"true":"false",firstRecovery.retryAttempted?"true":"false",firstRecovery.requested,firstRecovery.returned,firstRecovery.retryError,firstRecovery.retryPosBefore,firstRecovery.retryPosAfter,firstRecovery.latencyUs);
  Serial.printf("{\"type\":\"RECOVERY_STATS\",\"raw_handle_failures\":%u,\"reopen_success\":%u,\"reopen_failures\":%u,\"retry_success\":%u,\"retry_failures\":%u,\"recovered_R1\":%u,\"event_metadata_exhaustion\":%u,\"writer_queue_exhaustion\":%u,\"test_result_present\":%s,\"checkpoint_count\":%u,\"checkpoint_us_avg\":%.3f,\"checkpoint_us_max\":%u}\n",rawHandleFailures,reopenSuccess,reopenFailures,retrySuccess,retryFailures,retrySuccess,eventMetadataExhaustion,writerQueueExhaustion,testResultPresent?"true":"false",ls5CheckpointCount,ls5CheckpointCount?double(ls5CheckpointUsTotal)/ls5CheckpointCount:0,ls5CheckpointUsMax);
  Serial.printf("{\"type\":\"HARNESS_STATS\",\"writes_during_run\":%u,\"writes_during_finalization\":%u,\"last_write_us\":%llu}\n",writesDuringRun,writesDuringFinalization,lastWriteUs);
  if(exhaustionSnapValid){Serial.printf("{\"type\":\"POOL_EXHAUSTION\",\"sample\":%llu,\"ready_depth\":%u,\"writer_active\":%s,\"last_write_us\":%u,\"since_last_write_us\":%llu}\n",firstExhaustionSample,exhaustionReadyDepth,exhaustionWriterActive?"true":"false",exhaustionLastWriteLatency,exhaustionSinceLastWriteUs);for(uint32_t i=0;i<CHUNK_COUNT;i++){ChunkSnap&s=exhaustionSnap[i];Serial.printf("{\"type\":\"CHUNK_SNAPSHOT\",\"index\":%u,\"state\":%u,\"sample_start\":%llu,\"count\":%u,\"selected\":%s,\"stored\":%s,\"queued\":%s,\"writing\":%s}\n",i,s.state,s.start,s.count,s.selected?"true":"false",s.stored?"true":"false",s.state==CH_PENDING?"true":"false",s.state==WRITING?"true":"false");}}
}
void setup(){Serial.begin(115200);delay(1200);pinMode(14,OUTPUT);digitalWrite(14,HIGH);SPI.begin(1,3,2,14);bool sd=SD.begin(4,SPI,SD_HZ,"/sd",8);readyQ=xQueueCreate(CHUNK_COUNT,sizeof(Chunk*));for(uint32_t i=0;i<CHUNK_COUNT;i++)chunks[i]=(Chunk*)heap_caps_calloc(1,sizeof(Chunk),MALLOC_CAP_INTERNAL|MALLOC_CAP_DMA|MALLOC_CAP_8BIT);bool a=initAdc();xTaskCreate(adcTask,"adc",4096,nullptr,4,nullptr);xTaskCreate(writerTask,"writer",4096,nullptr,2,nullptr);Serial.printf("{\"type\":\"BOOT\",\"sd\":%s,\"adc\":%s,\"pool\":%s}\n",sd?"true":"false",a?"true":"false",chunks[11]?"true":"false");}
void loop(){if(runState==RS_STOP_REQUESTED)finish();printHarnessDiagnostics();if(active&&millis()-lastReport>=300000){lastReport=millis();Serial.printf("{\"type\":\"HEALTH\",\"elapsed_s\":%llu,\"samples\":%llu,\"events\":%u,\"lost\":%llu,\"dma_overflow\":%u,\"pool_exhaustion\":%u}\n",(esp_timer_get_time()-startedUs)/1000000ULL,acquired.load(),eventCount,lost.load(),dmaOverflow.load(),poolExhaustion);}if(Serial.available()){String c=Serial.readStringUntil('\n');c.trim();c.toUpperCase();if(c=="LS2STRESS10000"&&runState==RS_IDLE){runLs2EventStress(10000);}else if(c=="LS1TIME"){runLs1TimestampSelfTest();}else if(c=="LS1DUMP"){File f=SD.open(dirPath+"/session-start.json",FILE_READ);while(f&&f.available())Serial.write(f.read());if(f)f.close();Serial.println();}else if(c=="LS1START"&&runState==RS_IDLE){fieldStartCapture();}else if(c=="LS1STOP"&&runState==RS_RUNNING){fieldStopCapture();}else if(c=="LS1NEW"&&runState==RS_CLOSED){fieldNewSession();}else if(c=="RUN60"&&runState!=RS_RUNNING){resetDiagnosticRun();start(TEST60_US);}else if((c=="RUN600"||c=="RUN")&&runState!=RS_RUNNING){resetDiagnosticRun();start(TEST_US);}else if(c=="STOP"&&runState==RS_RUNNING){runState=RS_STOP_REQUESTED;active=false;}}delay(1);}
